import React from 'react';
import { CAddButton, Descriptions, Menu } from '@cloud-materials/common';

export default () => {
  const dropList = (
    <Menu onClickMenuItem={key => console.log(key)}>
      <Menu.Item key="1">菜单一</Menu.Item>
      <Menu.Item key="2">菜单二</Menu.Item>
      <Menu.Item key="3">菜单三</Menu.Item>
    </Menu>
  );
  const data = [
    ['Beijing', ['Haidian', 'Chaoyang', 'Daxing']],
    ['Shanghai', ['Pudong', 'Huangpu', 'Xuhui']],
    ['Guangzhou', ['Baiyun', 'Tianhe', 'Fanyu']],
    ['Shenzhen', ['Futian', 'Luohu', 'Nanshan']],
  ];

  const dropListMultiply = (
    <Menu>
      {data.map((city, outerIndex) => {
        if (city.length > 1) {
          const districts = city[1] as string[];
          return (
            <Menu.SubMenu key={String(outerIndex)} title={<span>{city[0]}</span>}>
              {districts.map((district, innerIndex) => {
                return <Menu.Item key={`${outerIndex}_${innerIndex}`}>{district}</Menu.Item>;
              })}
            </Menu.SubMenu>
          );
        }

        return <Menu.Item key={String(outerIndex)}>{city[0]}</Menu.Item>;
      })}
    </Menu>
  );

  return (
    <div>
      <Descriptions
        column={1}
        title="基础样式"
        data={[
          {
            label: '基本使用：',
            value: (
              <>
                <CAddButton type="primary" onClick={() => console.log('aaaa')} text="primary" />
                <CAddButton type="secondary" onClick={() => console.log('aaaa')} text="secondary" />
              </>
            ),
          },
          {
            label: '只展示Icon：',
            value: (
              <>
                <CAddButton type="primary" onClick={() => console.log('aaaa')} />
                <CAddButton type="secondary" onClick={() => console.log('aaaa')} />
              </>
            ),
          },
          {
            label: '默认的Tips：',
            value: (
              <CAddButton
                type="primary"
                onClick={() => console.log('aaaa')}
                text="展示Button后的tips"
                showEnableAddTips
              />
            ),
          },
          {
            label: 'enabledAddCount=5：',
            value: (
              <CAddButton
                type="primary"
                onClick={() => console.log('aaaa')}
                text="展示Button后的tips"
                showEnableAddTips
                enableAddCount={5}
              />
            ),
          },
          {
            label: '自定义的Tips：',
            value: (
              <CAddButton
                type="primary"
                onClick={() => console.log('aaaa')}
                text="展示Button后的tips"
                customTips={'我是自定义的Tips'}
              />
            ),
          },
          {
            label: 'popoverContent(优先级高于透传arco的属性)：',
            value: (
              <CAddButton
                type="primary"
                text="popover配置"
                popoverContent="我是按钮的popover内容"
                arcoPopoverProps={{ content: '透传arco的content' }}
              />
            ),
          },
          {
            label: 'arcoPopoverProps',
            value: (
              <CAddButton
                type="primary"
                text="popover配置"
                arcoPopoverProps={{ content: '透传arcoPopoverProps', position: 'bl' }}
              />
            ),
          },
          {
            label: 'dropdownList(优先级高于透传arco的组件属性)',
            value: (
              <CAddButton
                type="primary"
                text="下拉菜单"
                dropdownList={dropList}
                arcoDropdownProps={{ droplist: dropListMultiply }}
              />
            ),
          },
          {
            label: 'arcoDropdownProps：',
            value: <CAddButton type="primary" text="下拉菜单展示" arcoDropdownProps={{ droplist: dropList }} />,
          },
          {
            label: 'disabled',
            value: <CAddButton type="primary" text="下拉菜单展示" disabled dropdownList={dropList} />,
          },
          {
            label: '多级菜单',
            value: <CAddButton type="primary" text="多级菜单" dropdownList={dropListMultiply} />,
          },
          {
            label: 'dashed样式',
            value: <CAddButton type="dashed" text="添加模块" />,
          },
          {
            label: 'dashed样式-disabled',
            value: <CAddButton type="dashed" text="添加模块" disabled popoverContent={'popover'} />,
          },
        ]}
      />
    </div>
  );
};

import React from 'react';
import { Form, Menu, CAddButton, Typography, Tabs, Space, Table } from '@cloud-materials/common';

const FormItem = Form.Item;

export default () => {
  const dropList = (
    <Menu onClickMenuItem={key => console.log(key)}>
      <Menu.Item key="1">步骤一</Menu.Item>
      <Menu.Item key="2">步骤二</Menu.Item>
      <Menu.Item key="3">步骤三</Menu.Item>
    </Menu>
  );

  const tabs = [
    { title: 'tab1', key: 1 },
    { title: 'tab2', key: 2 },
    { title: 'tab3', key: 3 },
  ];

  return (
    <Space size={30} direction={'vertical'} style={{ width: '100%' }}>
      <Typography.Title heading={5}>1、内置于Form组件的添加按钮</Typography.Title>
      <Form autoComplete="off" title="表单" labelAlign="left" labelCol={{ span: 2 }}>
        <FormItem label="标签">
          <CAddButton type="primary" text="添加标签1" />
          <CAddButton type="primary" text="添加标签2" />
        </FormItem>
        <FormItem label="环境变量">
          <CAddButton type="primary" text="添加标签" enableAddCount={5} />
        </FormItem>
        <FormItem label="Label 标题">
          <CAddButton
            type="primary"
            text="添加 Label 标题"
            enableAddCount={0}
            showEnableAddTips
            popoverContent="数量已经添加够了"
          />
        </FormItem>
        <FormItem label="步骤">
          <CAddButton type="primary" text="添加步骤" dropdownList={dropList} />
        </FormItem>
        <CAddButton type="dashed" text="添加模块" />
      </Form>

      <Typography.Title heading={5}>2、用于Table中添加配置</Typography.Title>
      <Table
        columns={[
          { title: '1', dataIndex: 'col1' },
          { title: '2', dataIndex: 'col2' },
          { title: '3', dataIndex: 'col3' },
        ]}
        data={[{ key: 1, col1: 'data1', col2: 'data2', col3: 'data3' }]}
        footer={() => (
          <div style={{ textAlign: 'center' }}>
            <CAddButton type="primary" text="添加条目" style={{ padding: 0 }} />
          </div>
        )}
        pagination={false}
      />

      <Typography.Title heading={5}>3、用于Tab中添加容器</Typography.Title>
      <Tabs editable type="card-gutter" addButton={<CAddButton type="secondary" text="添加容器" />}>
        {tabs.map(x => (
          <Tabs.TabPane destroyOnHide key={x.key} title={x.title}>
            <Typography.Paragraph>Content of Tab Panel</Typography.Paragraph>
          </Tabs.TabPane>
        ))}
      </Tabs>
      <Tabs editable type="card-gutter" addButton={<CAddButton type="secondary" />}>
        {tabs.map(x => (
          <Tabs.TabPane destroyOnHide key={x.key} title={x.title}>
            <Typography.Paragraph>Content of Tab Panel</Typography.Paragraph>
          </Tabs.TabPane>
        ))}
      </Tabs>
    </Space>
  );
};
